/// <summary>
/// MPJ_19836 Customer Activity Statement Excel PDF. DCP 04/04/2022
/// The <c>PrintMgmtDelegatesHandler</c> class extension
/// </summary>
[ExtensionOf(classStr(PrintMgmtDelegatesHandler))]
final class KPMGPrintMgmtDelegatesHandler_Extension
{
}

Method.Source:
    /// <summary>
    ///    Retrieves the table that is used to define queries for the document type.
    ///    MPJ_19836 Customer Activity Statement Excel PDF. DCP 04/04/2022
    /// </summary>
    /// <returns>
    ///    The table ID of the table this document type queries at runtime.
    /// </returns>
    protected static TableId getQueryTableId(PrintMgmtDocumentType _docType)
    {
        TableId tableIdLoc;

        tableIdLoc = next getQueryTableId(_docType);

        switch (_docType)
        {
            case PrintMgmtDocumentType::KPMGMultiCustAccountStatement:
                tableIdLoc = tableNum(CustTable);
                break;
        }

        return tableIdLoc;
    }

    /// <summary>
    /// Determines the party type for a journal records and the current document type.
    /// MPJ_15231_Customer Statement DCP 14/02/2022
    /// </summary>
    /// <param name="_docType">
    /// Type of the document.
    /// </param>
    /// <param name="_jour">
    /// A journal record.
    /// </param>
    /// <returns>
    /// A member of <c>PrintMgmtPrintDestinationPartyType</c>.
    /// </returns>
    /// <exception cref="Exception::Error">
    /// An invalid combination of journal record and document type was found.
    /// </exception>
    protected static PrintMgmtPrintDestinationPartyType getPartyType(PrintMgmtDocumentType _docType, Common _jour)
    {
        PrintMgmtPrintDestinationPartyType  destinationPartyType = next getPartyType(_docType, _jour);

        if(_docType == PrintMgmtDocumentType::KPMGMultiCustAccountStatement)
        {
            destinationPartyType = PrintMgmtPrintDestinationPartyType::Customer;
        }

        return destinationPartyType;
    }
